    Ok(Record {
        fingerprint: fingerprint(source_file, line_no, raw),
        source_file: source_file.to_string(),
        line_no,
        raw_tick: tick,
        event,
        src_ip,
        user,
        user_agent: Some("ssh".to_string()),
        dest_ip: None,
        dest_port: Some(22),
        status,
        method: None,
        path: None,
        bytes: None,
    })
}

