use std::collections::BTreeMap;

use crate::config::{RuleConfig, RuleKind};
use crate::model::Record;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuleHit {
    pub rule_id: String,
    pub group_key: String,
    pub window_start: u64,
    pub event_time: u64,
    pub fingerprint: String,
}

fn group_key(record: &Record, fields: &[String]) -> String {
    fields
        .iter()
        .map(|f| record.group_value(f))
        .collect::<Vec<_>>()
        .join("|")
}

struct Grouped {
    records: Vec<(u64, Record)>,
}

fn group_records(records: Vec<Record>, rule: &RuleConfig) -> BTreeMap<String, Grouped> {
    let mut groups: BTreeMap<String, Grouped> = BTreeMap::new();
    for record in records {
        let key = group_key(&record, &rule.group_by);
        groups
            .entry(key)
            .or_insert_with(|| Grouped { records: Vec::new() })
            .records
            .push((record_event_time(&record), record));
    }
    for g in groups.values_mut() {
        g.records.sort_by_key(|(t, _)| *t);
    }
    groups
}

fn record_event_time(record: &Record) -> u64 {
    // Event time is injected by the pipeline into a parallel map; for engine
    // evaluation we carry it alongside. See evaluate() entry point.
    record
        .user
        .as_ref()
        .and_then(|_| None::<u64>)
        .unwrap_or(0)
}

