        .iter()
        .filter(|(_, r)| r.event == "http" && r.is_4xx())
        .cloned()
        .collect();
    matched.sort_by_key(|(t, _)| *t);
    let mut left = 0usize;
    for right in 0..matched.len() {
        while matched[right].0 - matched[left].0 > rule.window_secs {
            left += 1;
        }
        if (right - left + 1) as u32 >= rule.threshold {
