    use super::*;
    use crate::config::RuleKind;

    fn rec(event: &str, fp: &str, ip: &str, status: Option<u16>) -> Record {
        Record {
            fingerprint: fp.into(),
            source_file: "x".into(),
            line_no: 1,
            raw_tick: 0,
            event: event.into(),
            src_ip: ip.into(),
            user: None,
            user_agent: None,
            dest_ip: None,
            dest_port: None,
            status,
            method: None,
            path: None,
            bytes: None,
