        if count as u32 >= rule.threshold {
            let (t, record) = &matched[right];
            hits.push(RuleHit {
                rule_id: rule.id.clone(),
                group_key: key.to_string(),
                window_start: window_start(*t, rule.window_secs),
                event_time: *t,
                fingerprint: record.fingerprint.clone(),
            });
        }
    }
}

