//! Deterministic labelled fixture generator.
//!
//! Everything downstream consumes is a pure function of the seed. The generator
//! emits three raw log files (nginx / sshd / zeek) plus a `truth.jsonl` sidecar
//! containing ground-truth incident labels and the negative-cell denominator
//! used for the false-positive rate. Counts are intentionally constructed:
//!
//! * 3 logical segments of 800 sixty-second windows, separated by a 32-bit
//!   counter wrap -> exactly 2400 windows and 2 wraps;
//! * 11 windows each receive 13 late events -> 143 late / 11 restatements;
//! * 14 ground-truth incidents, one stealthy (FN) and one benign probe (FP);
//! * 58 dedicated burst entities for median+MAD anomaly sessions;
//! * 37 structurally invalid lines spread across the three files.

use std::collections::BTreeMap;
use std::fs::File;
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};

use serde::Serialize;

use crate::error::Result;
use crate::rng::Rng;

pub const WRAP_PERIOD: u64 = 1u64 << 32;
pub const SEGMENT_SECS: u64 = 48_000; // 800 windows * 60s
pub const WINDOW_LEN: u64 = 60;
pub const WINDOWS_PER_SEGMENT: u64 = SEGMENT_SECS / WINDOW_LEN;
pub const TOTAL_WINDOWS: u64 = 3 * WINDOWS_PER_SEGMENT;

const NORMAL_TOTAL: u64 = 80_000;
const LATE_WINDOWS: u64 = 11;
const LATE_PER_WINDOW: u64 = 13;
pub const LATE_TOTAL: u64 = LATE_WINDOWS * LATE_PER_WINDOW; // 143
const QUARANTINE_PER_FILE: [usize; 3] = [12, 13, 12]; // 37
const BURST_ENTITIES: u64 = 58;
const FP_CELLS: u64 = 3;
pub const NEGATIVE_CELLS: u64 = 200;

#[derive(Debug, Clone)]
struct Event {
    event_time: u64, // expanded logical seconds
    arrival_seq: u64,
    kind: EventKind,
    src_ip: String,
    user: Option<String>,
    ua: Option<String>,
    dest_ip: Option<String>,
    dest_port: Option<u16>,
    status: Option<u16>,
    method: Option<String>,
    path: Option<String>,
    bytes: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EventKind {
    Http,
    Ssh,
    Conn,
}

#[derive(Debug, Serialize)]
