/// Generate the full fixture set under `dir`. Returns the three log paths.
pub fn generate(dir: &Path, seed: u64) -> Result<Generated> {
    std::fs::create_dir_all(dir).map_err(|source| crate::error::Error::Io {
        path: dir.to_path_buf(),
        source,
    })?;
    let mut rng = Rng::new(seed);
    let mut events: Vec<Event> = Vec::with_capacity(NORMAL_TOTAL as usize);
    let mut truth: Vec<TruthRecord> = Vec::new();

    // Late windows are picked deterministically inside segment 0, never the
    // first window (which cannot be late) and spaced apart.
    let mut late_plans: Vec<LatePlan> = Vec::new();
    for k in 0..LATE_WINDOWS {
        let bin_global = 10 + k * 40; // 10,50,...,410
        late_plans.push(LatePlan {
            bin_global,
            count: LATE_PER_WINDOW,
        });
    }
    let late_bins: std::collections::HashSet<u64> =
        late_plans.iter().map(|p| p.bin_global).collect();

    // ---- 1. Background normal traffic --------------------------------------
    let normal_ips = make_ip_pool("10.1.", 60);
    let user_agents = vec![
        "Mozilla/5.0 (X11; Linux x86_64)",
        "curl/8.4.0",
        "Go-http-client/1.1",
        "python-requests/2.31",
        "Mozilla/5.0 (Macintosh)",
    ];
    let users = vec!["alice", "bob", "carol", "dave", "erin"];
    let paths = vec!["/", "/login", "/api/v1/health", "/static/app.js", "/metrics"];

    // Reserve a budget; scenarios and bursts consume the remainder.
    let mut emitted: u64 = 0;

    for i in 0..NORMAL_TOTAL {
        let bin_global = rng.next_below(TOTAL_WINDOWS);
        let within = rng.next_below(WINDOW_LEN);
        let event_time = bin_global * WINDOW_LEN + within;
        let kind_roll = rng.next_below(100);
        let kind = if kind_roll < 70 {
            EventKind::Http
        } else if kind_roll < 85 {
            EventKind::Ssh
        } else {
            EventKind::Conn
        };
        let ip = rng.choose(&normal_ips).clone();
        let event = build_background(kind, &mut rng, &ip, &user_agents, &users, &paths);
        events.push(Event {
            event_time: event_time + event.0,
            arrival_seq: 0,
            kind,
            src_ip: ip,
            user: event.1,
            ua: event.2,
            dest_ip: event.3,
            dest_port: event.4,
            status: event.5,
            method: event.6,
            path: event.7,
            bytes: event.8,
        });
        emitted += 1;
        let _ = i;
    }

    // ---- 2. Ground-truth incidents (14) ------------------------------------
    build_incidents(&mut events, &mut truth);

    // ---- 3. Benign probe producing the FP cells (3 cells, 1 merged alert) ---
    build_probe_fp(&mut events, &mut truth);

    // ---- 4. 58 burst entities for anomaly sessions -------------------------
    build_burst_entities(&mut events, &mut rng);

    // ---- 5. Late events ----------------------------------------------------
    build_late_events(&mut events, &late_plans);

    // Assign arrival sequence in event_time order, then re-order the late ones.
    events.sort_by_key(|e| e.event_time);
    // Re-introduce out-of-order arrival: shuffle slightly while keeping it a
    // permutation. Late events are explicitly scheduled after their window's
    // close point below.
    let total = events.len() as u64;
    for (idx, event) in events.iter_mut().enumerate() {
        event.arrival_seq = idx as u64;
    }
    schedule_late_arrivals(&mut events, &late_bins, total);

    // Deterministic final ordering for file writing: arrival order.
    events.sort_by_key(|e| e.arrival_seq);

    // ---- write files -------------------------------------------------------
    let nginx_path = dir.join("nginx.log");
    let sshd_path = dir.join("sshd.log");
    let zeek_path = dir.join("zeek.log");
    let mut nginx = BufWriter::new(File::create(&nginx_path)?);
    let mut sshd = BufWriter::new(File::create(&sshd_path)?);
    let mut zeek = BufWriter::new(File::create(&zeek_path)?);

    let mut line_counters: BTreeMap<EventKind, usize> = BTreeMap::new();
    for event in &events {
        let line_no = line_counters.get(&event.kind).copied().unwrap_or(0) + 1;
        line_counters.insert(event.kind, line_no);
        let raw = render_event(event);
        match event.kind {
            EventKind::Http => writeln!(nginx, "{raw}")?,
            EventKind::Ssh => writeln!(sshd, "{raw}")?,
            EventKind::Conn => writeln!(zeek, "{raw}")?,
        }
    }

    // Quarantine lines, deterministic and structurally invalid.
    write_quarantine(&mut nginx, EventKind::Http, QUARANTINE_PER_FILE[0])?;
    write_quarantine(&mut sshd, EventKind::Ssh, QUARANTINE_PER_FILE[1])?;
    write_quarantine(&mut zeek, EventKind::Conn, QUARANTINE_PER_FILE[2])?;

    nginx.flush()?;
    sshd.flush()?;
    zeek.flush()?;

    // ---- truth sidecar -----------------------------------------------------
    let truth_path = dir.join("truth.jsonl");
    let mut tf = BufWriter::new(File::create(&truth_path)?);
    writeln!(
        tf,
        "{}",
        serde_json::to_string(&serde_json::json!({
            "label": "summary",
            "rule_id": "*",
            "src_ip": "*",
            "window_start": 0,
            "expected": "summary",
            "detail": serde_json::json!({
                "total_incidents": 14,
                "expected_tp": 13,
                "expected_fn": 1,
                "deduped_fp_alerts": 1,
                "fp_cells": FP_CELLS,
                "negative_cells": NEGATIVE_CELLS,
                "anomalous_sessions": BURST_ENTITIES,
                "total_windows": TOTAL_WINDOWS,
                "late_events": LATE_TOTAL,
                "restatements": LATE_WINDOWS,
                "wraparounds": 2,
                "quarantined": 37,
                "parsed": NORMAL_TOTAL,
            })
        }))?
    )?;
    for record in &truth {
        writeln!(tf, "{}", serde_json::to_string(record)?)?;
    }
    tf.flush()?;

    Ok(Generated {
        files: vec![nginx_path, sshd_path, zeek_path],
        truth_path,
    })
}

