        EventKind::Http => {
            let status_roll = rng.next_below(100);
            let status = if status_roll < 88 {
                200
            } else if status_roll < 95 {
                404
            } else if status_roll < 98 {
                301
            } else {
                500
            };
            (
                0,
                None,
                Some(rng.choose(uas).to_string()),
                None,
                None,
                Some(status),
                Some(rng.choose(&["GET", "POST"]).to_string()),
                Some(rng.choose(paths).to_string()),
                Some(rng.next_range(100, 5000)),
            )
        }
        EventKind::Ssh => (
            0,
            Some(rng.choose(users).to_string()),
            Some("ssh".to_string()),
            None,
            Some(22),
            Some(200),
            None,
            None,
            None,
        ),
        EventKind::Conn => (
            0,
            None,
            Some(rng.choose(uas).to_string()),
            Some("10.0.0.2".to_string()),
            Some(443),
            Some(200),
            None,
            None,
            Some(rng.next_range(64, 1500)),
