fn build_scenarios(rng: &mut Rng, planned: &mut Vec<Planned>, labels: &mut TruthLabel, start: u64) {
    let attack_ips = ip_pool("203.0.113", ATTACK_INCIDENTS as usize);
    let mut cursor = start;

    // 1..=5: brute force -> success (ssh_fail_then_success / r02).
    for idx in 0..5u64 {
        let ip = &attack_ips[idx as usize];
        let t0 = cursor;
        let mut t = t0;
        for _ in 0..6 {
            push(planned, t, "sshd", sshd_line(t, ip, "fail"));
            t += 3;
        }
        push(planned, t, "sshd", sshd_line(t, ip, "success"));
        labels.push(truth("r02", ip, t0, t + 1, true));
        cursor = t + 240;
    }

    // 6..=9: http 4xx burst then login success (r04).
    for idx in 5..9u64 {
        let ip = &attack_ips[idx as usize];
        let t0 = cursor;
        let mut t = t0;
        for _ in 0..5 {
            push_http(planned, t, ip, 403, "Mozilla/5.0-X11");
            t += 8;
        }
        push(planned, t, "sshd", sshd_line(t, ip, "success"));
        labels.push(truth("r04", ip, t0, t + 1, true));
        cursor = t + 240;
    }

    // 10..=12: rapid conn scan (r05).
    for idx in 9..12u64 {
        let ip = &attack_ips[idx as usize];
        let t0 = cursor;
        for j in 0..12 {
            let t = t0 + j * 2;
            push(
                planned,
                t,
                "zeek",
                zeek_line(t, ip, "172.16.0.20", "scanner/1.0", rng),
            );
        }
        labels.push(truth("r05", ip, t0, t0 + 30, true));
        cursor = t0 + 240;
    }

    // 13: successful login without logout (r01 absent).
    {
        let ip = &attack_ips[12];
        let t0 = cursor;
        push(planned, t0, "sshd", sshd_line(t0, ip, "success"));
        labels.push(truth("r01", ip, t0, t0 + 120, true));
        cursor = t0 + 240;
    }

    // 14: stealthy slow-and-low intrusion (the false negative). Events are
    // spaced beyond every rule window so nothing fires, but it is labeled.
    {
        let ip = &attack_ips[13];
        let t0 = cursor;
        for j in 0..3 {
            let t = t0 + j * 400;
            push(planned, t, "sshd", sshd_line(t, ip, "fail"));
        }
        let ts = t0 + 1_300;
        push(planned, ts, "sshd", sshd_line(ts, ip, "success"));
        labels.push(truth("r02", ip, t0, ts + 1, true));
    }
}

fn truth(rule_id: &str, ip: &str, start: u64, end: u64, is_attack: bool) -> TruthLabel {
    TruthLabel {
        label_id: format!("{}-{}", rule_id, ip),
        rule_id: rule_id.to_string(),
        src_ip: ip.to_string(),
        start_sec: start,
        end_sec: end,
        is_attack,
    }
}

fn push(planned: &mut Vec<Planned>, expanded: u64, kind: &'static str, line: String) {
    let fp = format!("{kind}:{expanded}:{}", line.len());
    planned.push(Planned {
        expanded,
        tick: 0,
        kind,
        line,
        fingerprint_input: fp,
    });
}

fn push_http(planned: &mut Vec<Planned>, expanded: u64, ip: &str, status: u16, ua: &str) {
    let line = format!(
        "{ip} - - [{tick}] \"GET /admin HTTP/1.1\" {status} 311 \"-\" \"{ua}\"",
        ip = ip,
        tick = expanded % MOD,
        status = status,
        ua = ua
    );
    push(planned, expanded, "nginx", line);
}
