/// Render the three log files (in expanded-time order per file) plus the
/// malformed lines that must be quarantined.
fn write_logs(dir: &Path, planned: &[Planned]) -> Result<Vec<GeneratedFile>> {
    let names = [
        ("nginx", "nginx.log"),
        ("sshd", "sshd.log"),
        ("zeek", "zeek.log"),
    ];
    let mut files = Vec::new();
    for (kind, file_name) in names {
        let path = dir.join(file_name);
        let mut out = String::new();
        for event in planned.iter().filter(|e| e.kind == kind) {
            out.push_str(&event.line);
            out.push('\n');
        }
        if kind == "zeek" {
            append_bad_lines(&mut out, QUARANTINED);
        }
        std::fs::write(&path, out).map_err(|source| crate::error::Error::Io {
            path: path.clone(),
            source,
        })?;
        files.push(GeneratedFile {
            path,
            kind,
        });
    }
    Ok(files)
}

fn append_bad_lines(out: &mut String, count: u64) {
    for i in 0..count {
        // Structurally broken in different, deterministic ways.
        let bad = match i % 4 {
            0 => "this line is not a known format".to_string(),
            1 => format!("\t\t\t\t"),
            2 => "999.999.999.999 - - [notanumber] \"GET / HTTP/1.1\" 200 10 \"-\" \"x\"".to_string(),
            _ => format!("garbled-sshd entry {} without marker", i),
        };
        out.push_str(&bad);
        out.push('\n');
    }
}

/// Write the arrival-order manifest. Late events are pushed toward the tail so
/// they arrive after their owning window has closed.
fn write_manifest(
    dir: &Path,
    planned: &[Planned],
    late_set: &std::collections::HashSet<usize>,
) -> Result<PathBuf> {
    let mut on_time: Vec<usize> = (0..planned.len()).filter(|i| !late_set.contains(i)).collect();
    let mut late: Vec<usize> = late_set.iter().copied().collect();
    on_time.sort_by_key(|i| planned[*i].expanded);
    late.sort_by_key(|i| planned[*i].expanded);

    let mut order: Vec<usize> = on_time;
    order.extend(late);

