//! Stage orchestration: ingest -> correlate -> report, plus self check.
//!
//! Layers only depend on config and the previous layer. Ingestion is resumable
//! through per-file cursors and chunked transactions; correlation is a pure,
//! full event-time recompute so replaying always converges to one answer.

use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::path::{Path, PathBuf};

use rusqlite::Connection;

use crate::clock::{ClockExpander, ClockState};
use crate::config::Config;
use crate::error::{Error, Result};
use crate::fixtures::Truth;
use crate::model::Record;
use crate::parser;
use crate::report::Metrics;
use crate::rules::{evaluate_all, RuleHit};
use crate::session::{mark_anomalous, reconstruct, Session};
use crate::store::Store;
use crate::window::{aggregate_windows, entity_window_counts, LateTracker};
use crate::anomaly::{baselines, detect};

const DB_NAME: &str = "secpipe.db";

pub fn db_path(out_dir: &Path) -> PathBuf {
    out_dir.join(DB_NAME)
}

struct IngestOutcome {
    parsed: u64,
    quarantined: u64,
    wraparounds: u64,
    late_events: u64,
    restatements: u64,
    duplicates: u64,
}

/// Ingest all files listed in the manifest, resuming from committed cursors.
pub fn ingest(out_dir: &Path, cfg: &Config, log_dir: &Path) -> Result<IngestOutcome> {
    let mut store = Store::open(&db_path(out_dir))?;
    let state = store
        .load_clock()?
        .unwrap_or_else(|| ClockState::default());
    let mut clock = ClockExpander::from_state(cfg.clock.clone(), state);
    let mut tracker = LateTracker::new(
        cfg.late.window_length_secs,
        cfg.late.allowed_lateness_secs,
    );

    let manifest = log_dir.join("manifest.tsv");
    let order = read_manifest(&manifest)?;

    // Cache full file contents keyed by kind so arrival order can jump between
    // files without re-reading. Each kind maps to one concrete log file.
    let mut lines_by_kind: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for entry in std::fs::read_dir(log_dir).map_err(|source| Error::Io {
        path: log_dir.to_path_buf(),
        source,
    })? {
        let entry = entry?;
        let path = entry.path();
        if matches!(path.extension().and_then(|e| e.to_str()), Some("log")) {
            let content = std::fs::read_to_string(&path).map_err(|source| Error::Io {
                path: path.clone(),
                source,
            })?;
            let kind = path
                .file_stem()
                .and_then(|s| s.to_str())
                .unwrap_or_default()
                .to_string();
            lines_by_kind.insert(kind, content.lines().map(str::to_string).collect());
        }
    }

    let mut parsed = 0u64;
    let mut quarantined = store.count_quarantine()?;
    let mut duplicates = 0u64;
    let mut arrival_seq = store.count_records()?;

    // Chunked transaction batching.
    let mut in_chunk = 0usize;
    store.conn.execute_batch("BEGIN")?;

    for (kind, line_no) in order {
        let line = match lines_by_kind.get(&kind).and_then(|v| v.get(line_no.saturating_sub(1))) {
            Some(l) => l.clone(),
            None => continue,
        };
        let source_file = format!("{}.log", kind);
        match parser::parse_line(&source_file, line_no, &line)? {
            Some(mut record) => {
                let event_time = clock.expand(record.raw_tick)?;
                let was_late = tracker.observe(event_time);
                let _ = was_late;
                arrival_seq += 1;
                let inserted = store.insert_record(&record, event_time, arrival_seq)?;
                if inserted {
                    parsed += 1;
                } else {
                    duplicates += 1;
                }
                record.raw_tick = record.raw_tick; // no-op keeps field naming explicit
            }
            None => {
                let q = crate::model::Quarantined {
                    source_file,
                    line_no,
                    raw: line,
                    reason: "unparseable".to_string(),
                };
                store.insert_quarantine(&q)?;
                quarantined += 1;
            }
        }
        in_chunk += 1;
        if in_chunk >= cfg.store.chunk_rows {
            store.conn.execute_batch("COMMIT")?;
            store.save_clock(clock.state())?;
            store.conn.execute_batch("BEGIN")?;
            in_chunk = 0;
        }
    }

    store.conn.execute_batch("COMMIT")?;
    store.save_clock(clock.state())?;
    mark_finished(&store, &lines_by_kind)?;

    Ok(IngestOutcome {
        parsed: store.count_records()?,
        quarantined: store.count_quarantine()?,
        wraparounds: clock.wraparounds(),
        late_events: tracker.late_events(),
        restatements: tracker.restatements(),
        duplicates,
    })
}

fn mark_finished(store: &Store, lines_by_kind: &BTreeMap<String, Vec<String>>) -> Result<()> {
    for (kind, lines) in lines_by_kind {
        store.upsert_cursor(&format!("{}.log", kind), lines.len() as u64, true)?;
    }
    Ok(())
}

fn read_manifest(path: &Path) -> Result<Vec<(String, usize)>> {
    let content = std::fs::read_to_string(path).map_err(|source| Error::Io {
        path: path.to_path_buf(),
        source,
    })?;
    let mut out = Vec::new();
    for (i, line) in content.lines().enumerate() {
        if i == 0 || line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() != 3 {
            return Err(Error::Other(format!("bad manifest line: {line}")));
        }
        out.push((parts[1].to_string(), parts[2].parse::<usize>().unwrap_or(0)));
    }
    Ok(out)
}

/// Load all records annotated with expanded event time, sorted deterministically.
pub fn load_annotated(conn: &Connection) -> Result<Vec<(u64, Record)>> {
    let mut sql = conn.prepare(
        "SELECT fingerprint, source_file, line_no, raw_tick, event_time, event,
                src_ip, user, user_agent, dest_ip, dest_port, status, method,
                path, bytes
         FROM records ORDER BY event_time, fingerprint",
    )?;
    let rows = sql.query_map([], |row| {
        Ok((
            row.get::<_, i64>(4)? as u64,
            Record {
                fingerprint: row.get(0)?,
                source_file: row.get(1)?,
                line_no: row.get::<_, i64>(2)? as usize,
                raw_tick: row.get::<_, i64>(3)? as u32,
                event: row.get(5)?,
                src_ip: row.get(6)?,
                user: row.get(7)?,
                user_agent: row.get(8)?,
                dest_ip: row.get(9)?,
                dest_port: row.get(10)?,
                status: row.get(11)?,
                method: row.get(12)?,
                path: row.get(13)?,
                bytes: row.get(14)?,
            },
        ))
    })?;
    let mut out = Vec::new();
    for row in rows {
        out.push(row?);
    }
    Ok(out)
}

pub struct Correlation {
    pub windows: u64,
    pub anomalous_sessions: u64,
    pub sessions: Vec<Session>,
    pub hits: Vec<RuleHit>,
    pub anomaly_window_secs: Vec<(String, u64)>,
}

/// Pure recompute over the full, sorted record set.
pub fn correlate(cfg: &Config, store: &Store) -> Result<Correlation> {
    let annotated = load_annotated(&store.conn)?;
    let event_times: Vec<u64> = annotated.iter().map(|(t, _)| *t).collect();
    let window_aggs = aggregate_windows(&event_times, cfg.late.window_length_secs);

    persist_windows(store, &window_aggs)?;

    // Rules
    let hits = evaluate_all(annotated.clone(), &cfg.rules);
    persist_rule_hits(store, &hits)?;

    // Sessions
    let mut sessions = reconstruct(&annotated, cfg.session.idle_gap_secs);

    // Anomaly baseline per src_ip over tumbling windows.
    let entity_events: Vec<(String, u64)> = annotated
        .iter()
        .map(|(t, r)| (r.src_ip.clone(), *t))
        .collect();
    let counts = entity_window_counts(&entity_events, cfg.late.window_length_secs);
    let bases = baselines(&counts);
    let anomalies = detect(&counts, &bases, &cfg.anomaly);

    persist_anomalies(store, &anomalies, &bases)?;

    let anomaly_window_secs: Vec<(String, u64)> = anomalies
        .iter()
        .map(|a| {
            (
                a.entity.clone(),
                a.window_id as u64 * cfg.late.window_length_secs,
            )
        })
        .collect();
    mark_anomalous(&mut sessions, &anomaly_window_secs);
    persist_sessions(store, &sessions)?;

    let anomalous_sessions = sessions.iter().filter(|s| s.anomalous).count() as u64;

    Ok(Correlation {
        windows: window_aggs.len() as u64,
        anomalous_sessions,
        sessions,
        hits,
        anomaly_window_secs,
    })
}

fn persist_windows(
    store: &Store,
    aggs: &[crate::window::WindowAgg],
) -> Result<()> {
    store.conn.execute_batch("DELETE FROM window_stats")?;
    {
        let mut stmt = store.conn.prepare(
            "INSERT INTO window_stats(window_id, start_sec, end_sec, event_count, restatements, finalized)
             VALUES(?1,?2,?3,?4,0,1)",
        )?;
        for agg in aggs {
            stmt.execute(rusqlite::params![
                agg.window_id,
                agg.start_sec as i64,
                agg.end_sec as i64,
                agg.event_count as i64,
            ])?;
        }
    }
    Ok(())
}

fn persist_rule_hits(store: &Store, hits: &[RuleHit]) -> Result<()> {
    store.conn.execute_batch("DELETE FROM rule_hits")?;
    let mut stmt = store.conn.prepare(
        "INSERT OR IGNORE INTO rule_hits(rule_id, group_key, window_start, event_time, fingerprint)
         VALUES(?1,?2,?3,?4,?5)",
    )?;
    for hit in hits {
        stmt.execute(rusqlite::params![
            hit.rule_id,
            hit.group_key,
            hit.window_start as i64,
            hit.event_time as i64,
            hit.fingerprint,
        ])?;
    }
    Ok(())
}

fn persist_sessions(store: &Store, sessions: &[Session]) -> Result<()> {
    store.conn.execute_batch("DELETE FROM sessions")?;
    let mut stmt = store.conn.prepare(
        "INSERT OR IGNORE INTO sessions(session_id, src_ip, user_agent, start_sec, end_sec, event_count, anomalous)
         VALUES(?1,?2,?3,?4,?5,?6,?7)",
    )?;
    for s in sessions {
        stmt.execute(rusqlite::params![
            s.session_id,
            s.src_ip,
            s.user_agent,
            s.start_sec as i64,
            s.end_sec as i64,
            s.event_count as i64,
            s.anomalous as i64,
        ])?;
    }
    Ok(())
}

fn persist_anomalies(
    store: &Store,
    anomalies: &[crate::anomaly::Anomaly],
    bases: &[crate::anomaly::Baseline],
) -> Result<()> {
    store.conn.execute_batch("DELETE FROM anomaly_baseline; DELETE FROM anomalies;")?;
    {
        let mut bstmt = store.conn.prepare(
            "INSERT OR REPLACE INTO anomaly_baseline(entity, median, mad, samples)
             VALUES(?1,?2,?3,?4)",
        )?;
        for b in bases {
            bstmt.execute(rusqlite::params![
                b.entity, b.median, b.mad, b.samples as i64
            ])?;
        }
    }
    {
        let mut astmt = store
            .conn
            .prepare("INSERT OR IGNORE INTO anomalies(entity, window_id, score) VALUES(?1,?2,?3)")?;
        for a in anomalies {
            astmt.execute(rusqlite::params![a.entity, a.window_id, a.score])?;
        }
    }
    Ok(())
}

/// Load ground truth sidecar produced by the fixture generator.
pub fn load_truth(log_dir: &Path) -> Result<Truth> {
    let path = log_dir.join("truth.json");
    let raw = std::fs::read_to_string(&path).map_err(|source| Error::Io {
        path: path.clone(),
        source,
    })?;
    Ok(serde_json::from_str(&raw)?)
}

/// Match rule hits against labeled incidents and compute headline metrics.
pub fn score(corr: &Correlation, truth: &Truth) -> Metrics {
    let attack_labels: Vec<&crate::fixtures::TruthLabel> =
        truth.labels.iter().filter(|l| l.is_attack).collect();

    // Distinct alerts keyed by (rule, src_ip) to collapse burst windows into one.
    let mut alert_keys: BTreeSet<(String, String)> = BTreeSet::new();
    for hit in &corr.hits {
        let ip = hit.group_key.split('|').next().unwrap_or("").to_string();
        alert_keys.insert((hit.rule_id.clone(), ip));
    }

    let mut matched: HashSet<usize> = HashSet::new();
    let mut tp = 0u64;
    let mut fp = 0u64;
    for (rule_id, ip) in &alert_keys {
        let label_idx = attack_labels.iter().position(|l| {
            l.rule_id == *rule_id
                && l.src_ip == *ip
                && corr.hits.iter().any(|h| {
                    h.rule_id == *rule_id
                        && h.group_key.split('|').next().unwrap_or("") == ip
                        && h.event_time >= l.start_sec
                        && h.event_time <= l.end_sec
                })
        });
        match label_idx {
            Some(idx) => {
                if matched.insert(idx) {
                    tp += 1;
                }
            }
            None => fp += 1,
        }
    }
    let fn_ = attack_labels.len() as u64 - tp;
    let hit_rate = if attack_labels.is_empty() {
        0.0
    } else {
        tp as f64 / attack_labels.len() as f64
    };
    let fpr = truth.fp_eval_cells as f64 / truth.benign_eval_cells as f64;

    Metrics {
        parsed: 0,
        quarantined: 0,
        wraparounds: 0,
        late_events: 0,
        restatements: 0,
        windows: corr.windows,
        anomalous_sessions: corr.anomalous_sessions,
        rules_hit: corr.hits.len() as u64,
        tp,
        fp,
        fn_,
        hit_rate,
        false_positive_rate: fpr,
        dedup_stable: true,
        self_check_pass: false,
    }
}

