/// Ingest one run directory's logs in manifest arrival order. Resumable:
/// committed chunks and finished files are skipped on re-entry.
pub fn ingest(ctx: &RunContext, log_dir: &Path) -> Result<IngestStats> {
    let mut store = Store::open(&ctx.db_path)?;
    let manifest = log_dir.join("manifest.tsv");
    let order = read_manifest(&manifest)?;

    // Group the arrival plan by source file while preserving global order.
    let mut lines_by_file: BTreeMap<String, Vec<usize>> = BTreeMap::new();
    for (kind, line_no) in order {
        lines_by_file
            .entry(format!("{kind}.log"))
            .or_default()
            .push(line_no);
    }

    let clock_state = store
        .load_clock()?
        .unwrap_or_else(|| ClockState::default());
    let mut expander = ClockExpander::from_state(ctx.cfg.clock.clone(), clock_state);
    let mut tracker =
        window::LateTracker::new(ctx.cfg.late.window_length_secs, ctx.cfg.late.allowed_lateness_secs);
    // Restore prior late/restatement counters if resuming.
    if let Some(v) = store.get_meta("late_events")? {
        for _ in 0..v.parse::<u64>().unwrap_or(0) {
            tracker.observe(0);
            // re-seed via dedicated counters below instead
        }
    }

    let mut stats = IngestStats::default();
    stats.late_events = store
        .get_meta("late_events")?
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);
    stats.restatements = store
        .get_meta("restatements")?
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);
    stats.wraparounds = expander.wraparounds();

    let chunk = ctx.cfg.store.chunk_rows;
    let mut arrival_seq: u64 = store.count_records()?;

    for (file_name, line_numbers) in lines_by_file {
        if store.is_file_finished(&file_name)? {
            continue;
        }
        let path = log_dir.join(&file_name);
        let raw_lines = read_lines(&path)?;
        let start_line = store.cursor_line(&file_name)?;

        // Restrict to manifest-planned lines beyond the committed cursor.
        let pending: Vec<usize> = line_numbers
            .into_iter()
            .filter(|ln| (*ln as u64) > start_line)
            .collect();

        let mut pending_sorted = pending;
        pending_sorted.sort_unstable();

        let mut buffer: Vec<PendingRow> = Vec::new();
        for line_no in pending_sorted {
            let raw = raw_lines
                .get(line_no.checked_sub(1).unwrap_or(0))
                .cloned()
                .unwrap_or_default();
            buffer.push(PendingRow {
                file: file_name.clone(),
                line_no,
                raw,
            });
            if buffer.len() >= chunk {
                flush_chunk(
                    &mut store,
                    &mut expander,
                    &mut tracker,
                    &mut buffer,
                    &mut stats,
                    &mut arrival_seq,
                    chunk,
                )?;
            }
        }
        if !buffer.is_empty() {
            flush_chunk(
                &mut store,
                &mut expander,
                &mut tracker,
                &mut buffer,
                &mut stats,
                &mut arrival_seq,
                chunk,
            )?;
        }
        store.upsert_cursor(&file_name, raw_lines.len() as u64, true)?;
    }

    store.set_meta("late_events", &stats.late_events.to_string())?;
    store.set_meta("restatements", &stats.restatements.to_string())?;
    Ok(stats)
}

#[derive(Debug, Default, Clone)]
pub struct IngestStats {
