    // After two identical ingests, duplicates equal the number of unique rows;
    // the helper reads total unique records so callers can verify the identity.
    let store = secpipe::store::Store::open(&ctx.db_path)?;
    Ok(store.count_records()?)
}

fn produce_report(
    ctx: &RunContext,
    logs: &Path,
    out: &Path,
    run_self_check: bool,
) -> secpipe::Result<()> {
    let truth_path = logs.join("truth.json");
    let truth: fixtures::Truth = serde_json::from_slice(&std::fs::read(&truth_path)?).map_err(
        |e| Error::Io {
            path: truth_path.clone(),
            source: std::io::Error::ErrorKind::Other.into(),
        },
    )?;
    let correlation = pipeline::correlate(ctx)?;
    let pass = if run_self_check {
        pipeline::self_check(ctx, &correlation).is_ok()
    } else {
        true
    };
    let store = secpipe::store::Store::open(&ctx.db_path)?;
    let stats = pipeline::IngestStats {
        wraparounds: store.load_clock()?.map(|c| c.wraparounds).unwrap_or(0),
        late_events: store
            .get_meta("late_events")?
            .and_then(|v| v.parse().ok())
            .unwrap_or(0),
        restatements: store
            .get_meta("restatements")?
            .and_then(|v| v.parse().ok())
            .unwrap_or(0),
        ..Default::default()
    };
    let snap = pipeline::snapshot(&store, &stats)?;
    let metrics =
        pipeline::evaluate_metrics(&correlation, &truth, &snap, true, pass);
    report::write_artifacts(out, &metrics)?;
    println!("{}", metrics.summary_line());
    if run_self_check && !pass {
        return Err(Error::SelfCheck("self check failed".into()));
    }
    Ok(())
}
