            let stats = pipeline::ingest(&ctx, &logs)?;
            println!(
                "inserted={} duplicate={} quarantined={} late_events={} restatements={} wraparounds={}",
                stats.inserted,
                stats.duplicate,
                stats.quarantined,
                stats.late_events,
                stats.restatements,
                stats.wraparounds
            );
            Ok(())
        }
        Command::Correlate { config, db } => {
            let cfg = Config::load(&config)?;
            let ctx = RunContext::new(cfg, db.parent().unwrap_or(Path::new(".")));
            let correlation = pipeline::correlate(&ctx)?;
            println!(
                "windows={} rules_hit={} anomalous_sessions={}",
                correlation.windows,
                correlation.rule_hits.len(),
                correlation.anomalous_sessions
            );
            Ok(())
        }
        Command::Report {
            config,
            db,
            logs,
            out,
            self_check,
        } => {
            let cfg = Config::load(&config)?;
            let ctx = RunContext::new(cfg, db.parent().unwrap_or(Path::new(".")));
            produce_report(&ctx, &logs, &out, self_check)?;
            Ok(())
        }
        Command::All {
            config,
            seed,
            out,
            self_check,
        } => {
            let cfg = Config::load(&config)?;
            std::fs::create_dir_all(&out).map_err(|source| Error::Io {
                path: out.clone(),
                source,
            })?;
            let log_dir = out.join("logs");
            let generation = fixtures::generate(&log_dir, seed)?;
            let ctx = RunContext::new(cfg, &out);

            // First ingestion.
            let stats = pipeline::ingest(&ctx, &log_dir)?;
            let store = secpipe::store::Store::open(&ctx.db_path)?;
            let snapshot = pipeline::snapshot(&store, &stats)?;
            drop(store);

            // Duplicate import: fingerprint conflicts must be counted, not
            // overwrite, and every derived metric must remain identical.
            let re_stats = pipeline::ingest(&ctx, &log_dir)?;
            let store2 = secpipe::store::Store::open(&ctx.db_path)?;
            let re_snapshot = pipeline::snapshot(&store2, &re_stats)?;
            let dedup_stable = snapshot.parsed == re_snapshot.parsed
                && snapshot.quarantined == re_snapshot.quarantined
                && re_snapshot.parsed == re_stats.duplicate + first_inserted(&ctx)?;
            drop(store2);

            let correlation = pipeline::correlate(&ctx)?;
            let truth: fixtures::Truth =
                serde_json::from_slice(&std::fs::read(&generation.truth)?).map_err(|e| {
                    Error::Io {
                        path: generation.truth.clone(),
                        source: std::io::Error::new(std::io::ErrorKind::InvalidData, e),
                    }
                })?;

            let mut pass = self_check;
            if self_check {
                pipeline::self_check(&ctx, &correlation)?;
                // Re-import stability check is part of the audit.
                if !dedup_stable {
                    return Err(Error::SelfCheck(
                        "duplicate import changed persisted row counts".into(),
                    ));
                }
            }
            let metrics = pipeline::evaluate_metrics(
                &correlation,
                &truth,
                &re_snapshot,
                dedup_stable,
                pass,
            );
            report::write_artifacts(&out, &metrics)?;
            println!("{}", metrics.summary_line());
            if self_check && !pass {
                return Err(Error::SelfCheck("self check failed".into()));
            }
            pass = true;
            Ok(())
        }
    }
}

fn first_inserted(ctx: &RunContext) -> secpipe::Result<u64> {
    // After two identical ingests, duplicates equal the number of unique rows;
    // the helper reads total unique records so callers can verify the identity.
    let store = secpipe::store::Store::open(&ctx.db_path)?;
    Ok(store.count_records()?)
}

fn produce_report(
    ctx: &RunContext,
    logs: &Path,
    out: &Path,
    run_self_check: bool,
) -> secpipe::Result<()> {
    let truth_path = logs.join("truth.json");
    let truth: fixtures::Truth = serde_json::from_slice(&std::fs::read(&truth_path)?).map_err(
        |e| Error::Io {
            path: truth_path.clone(),
            source: std::io::Error::ErrorKind::Other.into(),
        },
    )?;
    let correlation = pipeline::correlate(ctx)?;
    let pass = if run_self_check {
        pipeline::self_check(ctx, &correlation).is_ok()
    } else {
        true
    };
    let store = secpipe::store::Store::open(&ctx.db_path)?;
    let stats = pipeline::IngestStats {
        wraparounds: store.load_clock()?.map(|c| c.wraparounds).unwrap_or(0),
        late_events: store
            .get_meta("late_events")?
            .and_then(|v| v.parse().ok())
            .unwrap_or(0),
        restatements: store
            .get_meta("restatements")?
            .and_then(|v| v.parse().ok())
            .unwrap_or(0),
        ..Default::default()
    };
    let snap = pipeline::snapshot(&store, &stats)?;
    let metrics =
        pipeline::evaluate_metrics(&correlation, &truth, &snap, true, pass);
    report::write_artifacts(out, &metrics)?;
    println!("{}", metrics.summary_line());
    if run_self_check && !pass {
        return Err(Error::SelfCheck("self check failed".into()));
    }
    Ok(())
}
