"""const MOD: u64 = 1u64 << 32;
/// Active seconds within each 32-bit segment (800 windows * 60s).
const SEG_SPAN: u64 = SEGMENT_WINDOWS * WINDOW_LEN;

/// Map a dense segment-local time (0..SEG_SPAN) onto an expanded time that
/// straddles the 32-bit counter boundary so consecutive segments produce real
/// wraps in the raw tick stream. Segment 0 ends near 2^32, segment 1 starts
/// just after the first rollover, and so on.
fn seg_time(segment: u64, local: u64) -> u64 {
    segment * MOD + (MOD - SEG_SPAN) + local
}

/// Inverse of [`seg_time`] used when laying out scenario/burst events that are
/// expressed against a dense global window index.
fn expanded_for_window(window: u64, within: u64) -> u64 {
    let segment = window / SEGMENT_WINDOWS;
    let local_window = window % SEGMENT_WINDOWS;
    seg_time(segment, local_window * WINDOW_LEN + within)
}""")
