/// Ingest the same logs twice into a scratch DB and assert fingerprint-level
/// idempotency. Returns true only when the second import adds zero rows and
/// reports one conflict per unique record.
fn verify_dedup(
    cfg: &Config,
    out: &Path,
    log_dir: &Path,
) -> secpipe::Result<bool> {
    let scratch_dir = out.join("dedup-check");
    std::fs::create_dir_all(&scratch_dir).map_err(|source| Error::Io {
        path: scratch_dir.clone(),
        source,
    })?;
