                snapshot.parsed, snapshot.quarantined, re_snapshot.parsed,
                re_snapshot.quarantined, re_stats.inserted, re_stats.duplicate);
            drop(store2);

            let correlation = pipeline::correlate(&ctx)?;
            let truth_bytes = std::fs::read(&generation.truth).map_err(|source| Error::Io {
                path: generation.truth.clone(),
                source,
            })?;
            let truth: fixtures::Truth =
