    line=logs[kind][int(ln)-1]
    try: t=tick(kind,line)
    except: continue
    if prev is not None:
        d_=t-prev
        if d_<0:
            back+=1
            if len(examples)<5: examples.append((prev,t,d_))
        if abs(d_)>10000 and d_<0: big+=1
    prev=t
print("backward steps",back,"big wraps",big)
print("examples",examples[:5])
