fn replace_tick(line: &str, kind: &str, old: &str, new: &str) -> String {
    match kind {
        "nginx" => line.replacen(&format!("[{old}]"), &format!("[{new}]"), 1),
        "sshd" => {
            if let Some(rest) = line.strip_prefix(&format!("{old} ")) {
                format!("{new} {rest}")
