d='out/run21/logs'
logs={k:open(os.path.join(d,f'{k}.log')).read().splitlines() for k in ['nginx','sshd','zeek']}
def tick(kind,line):
    if kind=='nginx': return int(line.split('[')[1].split(']')[0])
    return int(line.split('\t' if kind=='zeek' else ' ')[0])
man=[l.split('\t') for l in open(os.path.join(d,'manifest.tsv')).read().splitlines()[1:]]
back=0; prev=None; ex=[]
for seq,kind,ln in man:
    line=logs[kind][int(ln)-1]
    try: t=tick(kind,line)
    except: continue
    if prev is not None and t<prev:
        back+=1
        if len(ex)<6: ex.append((prev,t))
    prev=t
print("backward",back,"examples",ex)
# also check distinct ticks count and file tick ranges
for k in logs:
    ts=[]
    for ln in logs[k]:
        try: ts.append(tick(k,ln))
        except: pass
    print(k,"min",min(ts),"max",max(ts),"n",len(ts))
