fn write_manifest(
    dir: &Path,
    planned: &[Planned],
    late_set: &std::collections::HashSet<usize>,
) -> Result<PathBuf> {
    // On-time rows arrive in the exact global (event-time, hence tick) order.
    let mut on_time: Vec<usize> = (0..planned.len()).filter(|i| !late_set.contains(i)).collect();
    on_time.sort_by(|a, b| {
        planned[*a]
            .expanded
            .cmp(&planned[*b].expanded)
            .then(planned[*a].kind.cmp(&planned[*b].kind))
            .then(planned[*a].fingerprint_input.cmp(&planned[*b].fingerprint_input))
    });
    let mut late: Vec<usize> = late_set.iter().copied().collect();
    late.sort_by_key(|i| planned[*i].expanded);

    let mut order: Vec<usize> = on_time;
    order.extend(late);

    let manifest = dir.join("manifest.tsv");

