            .cmp(&planned[*b].expanded)
            .then(planned[*a].kind.cmp(&planned[*b].kind))
            .then(planned[*a].fingerprint_input.cmp(&planned[*b].fingerprint_input))
    });
    let mut late: Vec<usize> = late_set.iter().copied().collect();
    late.sort_by_key(|i| planned[*i].expanded);

