        // current watermark tick, then step backward by the lateness budget.
        let anchor_id = natural.get(arrival_pos.min(natural.len() - 1)).copied().unwrap_or(*id);
        let watermark_tick = planned[anchor_id].tick;
        let late_tick = watermark_tick.saturating_sub(lateness_drift).max(1);
        let event = &mut planned[*id];
        event.tick = late_tick;
        event.line = replace_tick(&event.line, &event.kind, "", &late_tick.to_string());
